from functools import lru_cache
G=['.88.88.','888888.','.88.8..','..888..','.......','.......','.......']
S={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x=='8'}
shapes=[]
for h in range(1,3):
 for w in range(1,3):
  pass
# tile square and L3
for r in range(7):
 for c in range(7):
  for dr in range(1,3):
   for dc in range(1,3):
    if dr==2 and dc==2:
     sh={(r+i,c+j) for i in range(2) for j in range(2)}
     if sh<=S: shapes.append((sh,1))
    # 2x2 missing one
    if dr==2 and dc==2:
     for miss in [(i,j) for i in range(2) for j in range(2)]:
      sh={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+miss[0],c+miss[1])}
      if sh<=S: shapes.append((sh,miss))
@lru_cache(None)
def solve(rem):
 rem=set(rem)
 if not rem:return []
 cell=min(rem)
 for sh,typ in shapes:
  if cell in sh and sh<=rem:
   rec=solve(tuple(sorted(rem-sh)))
   if rec is not None:return [(sh,typ)]+rec
 return None
ans=solve(tuple(sorted(S)))
print(len(S),ans)
if ans:
 out=[[0]*7 for _ in range(7)]
 for sh,t in ans:
  val=1 if t==1 else { (1,1):2,(1,0):3,(0,1):4,(0,0):5}[t]
  print(t, sorted(sh))
  for r,c in sh:out[r][c]=val
 print(*out,sep='\n')
